function F([string]$name){$main.GetField($name,$all).GetValue($window)}
$flow=$main.GetField('flowTools',$private).GetValue($window);$main.GetMethod('DisposeFlowTools',$private).Invoke($window,@())|Out-Null;$flow.Clear();$create=$main.GetMethod('CreateFlowTool',$private);function Tool([string]$kind,[string]$name){$create.Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
$producer=Tool SubpixelEdgeExtraction 'Product Edges';$smooth=Tool XldContourSmoothing 'Contour Denoise';$fit=Tool XldLineFitting 'Stable Line Fit';$smooth.SetInputBinding('XLD',$producer.ToolId,'XLD');$fit.SetInputBinding('XLD',$smooth.ToolId,'XLD');$smooth.Parameters.XldSmoothNumRegrPoints=7;foreach($tool in @($producer,$smooth,$fit)){$flow.Add($tool)}
$window.WindowStartupLocation=[Windows.WindowStartupLocation]::Manual;$window.Left=2;$window.Top=2;$window.Width=1900;$window.Height=1060;$window.Topmost=$true;$window.Show();$window.Activate()|Out-Null;Pump 500
$paths=Get-ChildItem -LiteralPath $temp -File | ForEach-Object FullName;$loadQueue=$main.GetMethods($private)|Where-Object{$_.Name-eq'LoadImageQueue'-and$_.GetParameters().Count-eq1}|Select-Object -First 1;$oneArg=New-Object 'object[]' 1;$oneArg[0]=[string[]]$paths;try{$loadQueue.Invoke($window,$oneArg)|Out-Null} catch [Reflection.TargetInvocationException] { throw $_.Exception.InnerException }
