(F 'FlowToolList').SelectedItem=$smooth;$main.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($smooth))|Out-Null;(F 'RightTabs').SelectedItem=(F 'DockConfigurationTab');(F 'DockConfigurationTabs').SelectedIndex=0;$main.GetMethod('RefreshResultOverlayLayers',$private).Invoke($window,@())|Out-Null;$main.GetMethod('ScheduleRefreshDisplay',$private).Invoke($window,@())|Out-Null;Pump 1000
